/*
/*
 * ptx answered `command not found`. PtxCommand.ts ports ptx.c 9.4 (fetched from the v9.4 tag): word
 * discovery by fastmap or -W regex, sentence/line contexts (-S), ignore/only/break files, the
 * tail/before/keyafter/head field layout with truncation flags (-F), the dumb, roff and TeX outputs,
 * automatic and input references (-A, -r, -R), traditional mode (-G with an output operand), and the
 * option diagnostics. GNU regexps are translated from the emacs syntax ptx compiles with (`+` and `?`
 * are operators, `\\+` is a literal plus). Widths count bytes, as the real ptx does.
 *
 * Every expected string was produced by the real GNU coreutils 9.4 of the dev container, by running
 * the identical line in bash with LC_ALL=C.UTF-8 (typographic quotes normalised, scratch directory
 * rewritten to /tmp/ff). Cases where the real ptx loops forever (-W with a pattern matching the empty
 * string) are not pinned.
 *
 * Measured against the commit before (worktree): 134 cases; the command did not exist, all of them fall.
 */
import { describe, it, expect } from 'vitest';
import { LinuxPC } from '@/network/devices/LinuxPC';

type Sh = { executeCommand(line: string): Promise<string>; executor: { runAsUser(user: string, run: () => Promise<string>): Promise<string> } };

const SETUP = "printf 'the quick brown fox\njumps over the lazy dog\n' > t1; printf 'Hello world. This is a test.  Another sentence here! And more?\nsecond line of text, with punctuation: yes.\n' > t2; printf 'ref1 the quick brown fox jumps\nref2 over the lazy dog again\nref3 a very long line with many words to force truncation of the context on both sides of the keyword indeed\n' > t3; printf 'the\nover\n' > ign; printf 'fox\ndog\nquick\n' > only; printf ' .,:;' > brk; printf 'a b\\tc \"q\" $x_y {z} \\\\ %% # &\n' > t4; printf 'word1 word2\n' > t5; : > empty";

const normalise = (text: string): string => text.replace(/[\u2018\u2019]/g, "'").replace(/\n+$/, '');

async function lab(): Promise<Sh> {
  const machine = new LinuxPC('linux-pc', 'PC1', 0, 0) as unknown as Sh & { powerOn(): void };
  machine.powerOn();
  await machine.executeCommand('mkdir -p /tmp/ff; cd /tmp/ff');
  return machine;
}

